import shlex

def handle(query, state):
    """Simulate a system status page that runs shell-like commands to report service health.
    The page accepts a 'service' parameter and checks its status by 'running' the command.
    The simulated shell executor is vulnerable to OS command injection.
    """
    service = (query.get("service") or ["web"])[0]

    # Simulate a tiny in-memory shell executor.
    # Recognises: 'status <name>', 'cat <path>', and pipelines/semicolons.
    files = state.get("files", {})
    env_vars = state.get("env", {})

    def _run_cmd(cmd_str):
        """Execute a single command token list against the in-memory state."""
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = parts[1:]
        if prog == "status":
            svc = args[0] if args else ""
            services = state.get("services", {})
            info = services.get(svc)
            if info is None:
                return f"unknown service: {svc}"
            return f"{svc}: {info}"
        elif prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content
        elif prog == "echo":
            return " ".join(args)
        elif prog == "env":
            return "\n".join(f"{k}={v}" for k, v in env_vars.items())
        elif prog == "ls":
            path = args[0] if args else "/"
            # List files whose paths start with path
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            return "\n".join(sorted(entries)) if entries else ""
        else:
            return f"{prog}: command not found"

    def _eval_pipeline(pipeline_str):
        """Execute a semicolon-separated sequence of commands, return all output."""
        # Split on semicolons (outside quotes) — intentionally vulnerable.
        # We do a simple character scan to respect single/double quotes.
        segments = []
        current = []
        in_sq = False
        in_dq = False
        for ch in pipeline_str:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == ";" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            else:
                current.append(ch)
        segments.append("".join(current))

        outputs = []
        for seg in segments:
            out = _run_cmd(seg)
            if out:
                outputs.append(out)
        return "\n".join(outputs)

    # Build the command that the status page would "run" for the given service.
    # An attacker can inject additional commands after a semicolon.
    cmd = f"status {service}"
    output = _eval_pipeline(cmd)

    body = (
        "<html><head><title>System Status</title></head><body>"
        "<h1>System Status Dashboard</h1>"
        f"<pre>{output}</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
